from fastapi import FastAPI, Header
from fastapi.exceptions import HTTPException

app = FastAPI()

@app.get("/test")
async def test_header(my_underscore_header: str = Header(convert_underscores=True)):
    return {"header": my_underscore_header}

client = TestClient(app)

try:
    # This should fail with ValueError because my_underscore_header contains '_'
    client.get("/test", headers={"my_underscore_header": "test_value"})
except Exception as e:
    print(f"Caught exception: {type(e).__name__}: {e}")
    if isinstance(e, ValueError):
        print("Test Passed: ValueError raised as expected.")
    else:
        print("Test Failed: Wrong exception type raised.")
